/**
 * Arbitrary-precision signed integers.
 *
 * Python integers are unbounded, and this program routinely produces values
 * far wider than a machine word (a fraction built from two long literals
 * multiplies out immediately).  Everything here is therefore implemented from
 * first principles on top of a limb array.
 *
 * Representation
 * --------------
 *   sign : -1, 0 or 1   (0 if and only if the magnitude is empty)
 *   mag  : little-endian limbs in base 10^7, no leading zero limb
 *
 * Base 10^7 keeps every intermediate product below 10^14, comfortably inside
 * the exactly-representable range of a double, and makes decimal conversion a
 * matter of concatenating zero-padded limbs.
 */

const BASE = 10000000;
const LIMB_DIGITS = 7;

/* ------------------------------------------------------------------ *
 * Magnitude helpers -- plain little-endian limb arrays, always trimmed.
 * ------------------------------------------------------------------ */

function trim(mag) {
  let len = mag.length;
  while (len > 0 && mag[len - 1] === 0) len--;
  if (len !== mag.length) mag.length = len;
  return mag;
}

/** Compare two magnitudes: -1, 0 or 1. */
function magCompare(a, b) {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  for (let i = a.length - 1; i >= 0; i--) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return 0;
}

function magAdd(a, b) {
  const out = [];
  const n = a.length > b.length ? a.length : b.length;
  let carry = 0;
  for (let i = 0; i < n; i++) {
    const sum = (i < a.length ? a[i] : 0) + (i < b.length ? b[i] : 0) + carry;
    if (sum >= BASE) {
      out.push(sum - BASE);
      carry = 1;
    } else {
      out.push(sum);
      carry = 0;
    }
  }
  if (carry > 0) out.push(carry);
  return out;
}

/** a - b, requires a >= b. */
function magSub(a, b) {
  const out = [];
  let borrow = 0;
  for (let i = 0; i < a.length; i++) {
    let diff = a[i] - (i < b.length ? b[i] : 0) - borrow;
    if (diff < 0) {
      diff += BASE;
      borrow = 1;
    } else {
      borrow = 0;
    }
    out.push(diff);
  }
  return trim(out);
}

function magMul(a, b) {
  if (a.length === 0 || b.length === 0) return [];
  const out = new Array(a.length + b.length).fill(0);
  for (let i = 0; i < a.length; i++) {
    const ai = a[i];
    if (ai === 0) continue;
    let carry = 0;
    for (let j = 0; j < b.length; j++) {
      // ai*bj < 10^14, plus a limb and a carry: still exact in a double.
      const cur = out[i + j] + ai * b[j] + carry;
      carry = Math.floor(cur / BASE);
      out[i + j] = cur - carry * BASE;
    }
    let k = i + b.length;
    while (carry > 0) {
      const cur = out[k] + carry;
      carry = Math.floor(cur / BASE);
      out[k] = cur - carry * BASE;
      k++;
    }
  }
  return trim(out);
}

/** Multiply a magnitude by a small non-negative scalar (< BASE). */
function magMulSmall(a, k) {
  if (k === 0 || a.length === 0) return [];
  const out = [];
  let carry = 0;
  for (let i = 0; i < a.length; i++) {
    const cur = a[i] * k + carry;
    carry = Math.floor(cur / BASE);
    out.push(cur - carry * BASE);
  }
  while (carry > 0) {
    out.push(carry % BASE);
    carry = Math.floor(carry / BASE);
  }
  return trim(out);
}

/** Divide a magnitude by a small positive scalar (< BASE): [quotient, remainder]. */
function magDivModSmall(a, k) {
  const out = new Array(a.length).fill(0);
  let rem = 0;
  for (let i = a.length - 1; i >= 0; i--) {
    const cur = rem * BASE + a[i];
    const q = Math.floor(cur / k);
    out[i] = q;
    rem = cur - q * k;
  }
  return [trim(out), rem];
}

/**
 * Knuth's Algorithm D.  Returns [quotient, remainder] for non-negative
 * magnitudes; `v` must be non-empty.
 */
function magDivMod(u, v) {
  if (magCompare(u, v) < 0) return [[], u.slice()];
  if (v.length === 1) {
    const [q, r] = magDivModSmall(u, v[0]);
    return [q, r === 0 ? [] : [r]];
  }

  const n = v.length;
  const m = u.length - n;

  // Normalise so that the leading divisor limb is at least BASE/2.
  const d = Math.floor(BASE / (v[n - 1] + 1));
  const un = d === 1 ? u.slice() : magMulSmall(u, d);
  const vn = d === 1 ? v.slice() : magMulSmall(v, d);
  while (un.length < u.length + 1) un.push(0);

  const q = new Array(m + 1).fill(0);
  const vHigh = vn[n - 1];
  const vNext = vn[n - 2];

  for (let j = m; j >= 0; j--) {
    const numerator = un[j + n] * BASE + un[j + n - 1];
    let qhat = Math.floor(numerator / vHigh);
    let rhat = numerator - qhat * vHigh;
    while (qhat >= BASE || qhat * vNext > rhat * BASE + un[j + n - 2]) {
      qhat--;
      rhat += vHigh;
      if (rhat >= BASE) break;
    }

    // un[j .. j+n] -= qhat * vn
    let borrow = 0;
    let carry = 0;
    for (let i = 0; i < n; i++) {
      const product = qhat * vn[i] + carry;
      carry = Math.floor(product / BASE);
      let sub = un[i + j] - (product - carry * BASE) - borrow;
      if (sub < 0) {
        sub += BASE;
        borrow = 1;
      } else {
        borrow = 0;
      }
      un[i + j] = sub;
    }
    let top = un[j + n] - carry - borrow;
    if (top < 0) {
      top += BASE;
      borrow = 1;
    } else {
      borrow = 0;
    }
    un[j + n] = top;

    if (borrow === 1) {
      // qhat was one too large: give one multiple of the divisor back.
      qhat--;
      let addCarry = 0;
      for (let i = 0; i < n; i++) {
        const sum = un[i + j] + vn[i] + addCarry;
        if (sum >= BASE) {
          un[i + j] = sum - BASE;
          addCarry = 1;
        } else {
          un[i + j] = sum;
          addCarry = 0;
        }
      }
      un[j + n] = (un[j + n] + addCarry) % BASE;
    }
    q[j] = qhat;
  }

  const remScaled = trim(un.slice(0, n));
  const rem = d === 1 ? remScaled : magDivModSmall(remScaled, d)[0];
  return [trim(q), trim(rem)];
}

/** Parse a run of ASCII digits (no sign, no separators) into a magnitude. */
function magFromDigits(digits) {
  let start = 0;
  while (start < digits.length - 1 && digits.charCodeAt(start) === 48) start++;
  const body = digits.slice(start);
  if (body === '0') return [];

  const mag = [];
  for (let end = body.length; end > 0; end -= LIMB_DIGITS) {
    const begin = end - LIMB_DIGITS > 0 ? end - LIMB_DIGITS : 0;
    let limb = 0;
    for (let i = begin; i < end; i++) {
      limb = limb * 10 + (body.charCodeAt(i) - 48);
    }
    mag.push(limb);
  }
  return trim(mag);
}

function magToDecimal(mag) {
  if (mag.length === 0) return '0';
  let out = String(mag[mag.length - 1]);
  for (let i = mag.length - 2; i >= 0; i--) {
    out += String(mag[i]).padStart(LIMB_DIGITS, '0');
  }
  return out;
}

/** Number of decimal digits in a magnitude (0 counts as one digit). */
function magDecimalLength(mag) {
  if (mag.length === 0) return 1;
  let top = mag[mag.length - 1];
  let topDigits = 0;
  while (top > 0) {
    topDigits++;
    top = Math.floor(top / 10);
  }
  return (mag.length - 1) * LIMB_DIGITS + topDigits;
}

/* ------------------------------------------------------------------ *
 * Signed integer facade
 * ------------------------------------------------------------------ */

export class PyInt {
  /** @param {-1|0|1} sign @param {number[]} mag */
  constructor(sign, mag) {
    this.sign = mag.length === 0 ? 0 : sign;
    this.mag = mag;
  }

  /** Build from a safe machine integer (used only for the literals 1 and 3). */
  static fromSmall(value) {
    if (value === 0) return ZERO;
    const negative = value < 0;
    let rest = negative ? -value : value;
    const mag = [];
    while (rest > 0) {
      mag.push(rest % BASE);
      rest = Math.floor(rest / BASE);
    }
    return new PyInt(negative ? -1 : 1, trim(mag));
  }

  /**
   * Build from a sign and a string of ASCII digits.
   * @param {boolean} negative
   * @param {string} digits
   */
  static fromDigits(negative, digits) {
    const mag = magFromDigits(digits);
    return new PyInt(negative ? -1 : 1, mag);
  }

  isZero() {
    return this.sign === 0;
  }

  isNegative() {
    return this.sign < 0;
  }

  isOne() {
    return this.sign === 1 && this.mag.length === 1 && this.mag[0] === 1;
  }

  negate() {
    return new PyInt(-this.sign, this.mag.slice());
  }

  abs() {
    return this.sign < 0 ? new PyInt(1, this.mag.slice()) : this;
  }

  add(other) {
    if (this.sign === 0) return other;
    if (other.sign === 0) return this;
    if (this.sign === other.sign) {
      return new PyInt(this.sign, magAdd(this.mag, other.mag));
    }
    const cmp = magCompare(this.mag, other.mag);
    if (cmp === 0) return ZERO;
    if (cmp > 0) return new PyInt(this.sign, magSub(this.mag, other.mag));
    return new PyInt(other.sign, magSub(other.mag, this.mag));
  }

  subtract(other) {
    return this.add(other.negate());
  }

  multiply(other) {
    if (this.sign === 0 || other.sign === 0) return ZERO;
    return new PyInt(this.sign * other.sign, magMul(this.mag, other.mag));
  }

  /**
   * Truncating division: [quotient, remainder] with the remainder taking the
   * sign of the dividend.  Every division performed by this program is exact,
   * so the rounding convention never actually shows, but keeping it explicit
   * avoids surprises.
   */
  divMod(other) {
    const [qm, rm] = magDivMod(this.mag, other.mag);
    const quotient = new PyInt(this.sign * other.sign, qm);
    const remainder = new PyInt(this.sign, rm);
    return [quotient, remainder];
  }

  /** Exact quotient; callers guarantee divisibility. */
  divideExact(other) {
    return this.divMod(other)[0];
  }

  /** Compare against another integer: -1, 0 or 1. */
  compare(other) {
    if (this.sign !== other.sign) return this.sign < other.sign ? -1 : 1;
    if (this.sign === 0) return 0;
    const cmp = magCompare(this.mag, other.mag);
    return this.sign > 0 ? cmp : -cmp;
  }

  equals(other) {
    return this.compare(other) === 0;
  }

  /** Greatest common divisor, always non-negative (gcd(0, 0) == 0). */
  gcd(other) {
    let a = this.mag;
    let b = other.mag;
    // Small operands dominate in practice; a limb-pair fast path keeps the
    // common case cheap without giving up exactness (values stay below 10^14).
    if (a.length <= 2 && b.length <= 2) {
      let x = (a.length > 1 ? a[1] * BASE : 0) + (a.length > 0 ? a[0] : 0);
      let y = (b.length > 1 ? b[1] * BASE : 0) + (b.length > 0 ? b[0] : 0);
      while (y !== 0) {
        const t = x % y;
        x = y;
        y = t;
      }
      return PyInt.fromSmall(x);
    }
    while (b.length !== 0) {
      const r = magDivMod(a, b)[1];
      a = b;
      b = r;
    }
    return new PyInt(a.length === 0 ? 0 : 1, a);
  }

  /** Decimal digit count, ignoring the sign. */
  decimalLength() {
    return magDecimalLength(this.mag);
  }

  toString() {
    const body = magToDecimal(this.mag);
    return this.sign < 0 ? `-${body}` : body;
  }
}

export const ZERO = new PyInt(0, []);
export const ONE = new PyInt(1, [1]);

/**
 * The `int(str)` constructor and `str(int)` conversion, including the
 * interpreter's ceiling on decimal conversions.
 */

import { PyInt } from './integer.mjs';
import { PyValueError } from './errors.mjs';
import { decimalDigitValue, isPyWhitespace } from './unicode-data.mjs';
import { pyRepr } from './repr.mjs';

/** `sys.get_int_max_str_digits()` -- the interpreter default. */
export const MAX_STR_DIGITS = 4300;

const LIMIT_MESSAGE =
  `Exceeds the limit (${MAX_STR_DIGITS} digits) for integer string conversion; ` +
  'use sys.set_int_max_str_digits() to increase the limit';

/**
 * Parse text exactly as `int(text)` does for base 10:
 *
 *   - surrounding Unicode whitespace is discarded
 *   - an optional single '+' or '-' may follow, with no gap before the digits
 *   - digits are any Unicode decimal characters, mixed scripts allowed
 *   - single underscores are permitted between digits only
 *   - more than MAX_STR_DIGITS digits is refused outright
 *
 * @throws {PyValueError} on anything else.
 * @returns {PyInt}
 */
export function pyIntFromString(text) {
  const invalid = () =>
    new PyValueError(`invalid literal for int() with base 10: ${pyRepr(text)}`);

  const chars = Array.from(text);
  let start = 0;
  let end = chars.length;
  while (start < end && isPyWhitespace(chars[start].codePointAt(0))) start++;
  while (end > start && isPyWhitespace(chars[end - 1].codePointAt(0))) end--;

  let negative = false;
  if (start < end && (chars[start] === '+' || chars[start] === '-')) {
    negative = chars[start] === '-';
    start++;
  }
  if (start >= end) throw invalid();

  let digits = '';
  let previousWasDigit = false;
  for (let i = start; i < end; i++) {
    const ch = chars[i];
    if (ch === '_') {
      // Separators need a digit on both sides, and may not be doubled.
      if (!previousWasDigit || i + 1 >= end) throw invalid();
      previousWasDigit = false;
      continue;
    }
    const value = decimalDigitValue(ch.codePointAt(0));
    if (value < 0) throw invalid();
    digits += String(value);
    previousWasDigit = true;
  }
  if (!previousWasDigit) throw invalid();

  if (digits.length > MAX_STR_DIGITS) throw new PyValueError(LIMIT_MESSAGE);
  return PyInt.fromDigits(negative, digits);
}

/**
 * `str(value)`, subject to the same decimal-conversion ceiling.
 * @throws {PyValueError} when the value is too wide to render.
 */
export function pyIntToString(value) {
  if (value.decimalLength() > MAX_STR_DIGITS) throw new PyValueError(LIMIT_MESSAGE);
  return value.toString();
}
=== FRACTION ===
/**
 * The subset of `fractions.Fraction` this program exercises: construction from
 * two integers, addition, multiplication, true division in both operand
 * orders, ordering comparisons and `str()`.
 *
 * Every value is kept in lowest terms with a strictly positive denominator,
 * which is what makes the printed forms and the comparisons agree with
 * CPython without any further normalisation.
 */

import { PyInt, ONE } from '../core/integer.mjs';
import { PyZeroDivisionError, withFrames } from '../core/errors.mjs';
import { pyIntToString } from '../core/int-parse.mjs';

/**
 * Source locations the interpreter reports for failures raised inside the
 * library.  They are observable, because an escaping exception prints them.
 */
const FRAME_NEW = { file: 'fractions.py', line: 281, name: '__new__' };
const FRAME_STR = { file: 'fractions.py', line: 413, name: '__str__' };
const FRAME_FORWARD = { file: 'fractions.py', line: 620, name: 'forward' };
const FRAME_REVERSE = { file: 'fractions.py', line: 630, name: 'reverse' };
const FRAME_DIV = { file: 'fractions.py', line: 763, name: '_div' };

export class Fraction {
  /**
   * @param {PyInt} numerator
   * @param {PyInt} denominator  Must be non-zero.
   */
  constructor(numerator, denominator) {
    if (denominator.isZero()) {
      throw withFrames(
        new PyZeroDivisionError(`Fraction(${numerator.toString()}, 0)`),
        [FRAME_NEW],
      );
    }
    let divisor = numerator.gcd(denominator);
    if (denominator.isNegative()) divisor = divisor.negate();
    this.numerator = numerator.divideExact(divisor);
    this.denominator = denominator.divideExact(divisor);
  }

  /** Promote an integer, as the mixed-type operators do. */
  static fromInt(value) {
    return new Fraction(value, ONE);
  }

  /** Build directly from a pair already known to be coprime and positive-denominator. */
  static fromCoprime(numerator, denominator) {
    const result = Object.create(Fraction.prototype);
    result.numerator = numerator;
    result.denominator = denominator;
    return result;
  }

  plus(other) {
    const numerator = this.numerator
      .multiply(other.denominator)
      .add(other.numerator.multiply(this.denominator));
    const denominator = this.denominator.multiply(other.denominator);
    return reduced(numerator, denominator);
  }

  times(other) {
    return reduced(
      this.numerator.multiply(other.numerator),
      this.denominator.multiply(other.denominator),
    );
  }

  /** `self > other` -- denominators are positive, so cross-multiplying is safe. */
  greaterThan(other) {
    const left = this.numerator.multiply(other.denominator);
    const right = other.numerator.multiply(this.denominator);
    return left.compare(right) > 0;
  }

  /** `str(self)`; may fail when a component is too wide to render. */
  toDisplayString() {
    try {
      if (this.denominator.isOne()) return pyIntToString(this.numerator);
      return `${pyIntToString(this.numerator)}/${pyIntToString(this.denominator)}`;
    } catch (err) {
      throw withFrames(err, [FRAME_STR]);
    }
  }
}

/** Reduce a numerator/denominator pair with a known-positive denominator. */
function reduced(numerator, denominator) {
  const divisor = numerator.gcd(denominator);
  if (divisor.isOne()) return Fraction.fromCoprime(numerator, denominator);
  return Fraction.fromCoprime(
    numerator.divideExact(divisor),
    denominator.divideExact(divisor),
  );
}

/**
 * The division helper both operator directions funnel into.  It mirrors
 * CPython's partial cancellation, which is visible in the message of the
 * exception raised for a zero divisor.
 */
function divide(a, b) {
  let na = a.numerator;
  let da = a.denominator;
  let nb = b.numerator;
  let db = b.denominator;

  const g1 = na.gcd(nb);
  if (!g1.isOne() && !g1.isZero()) {
    na = na.divideExact(g1);
    nb = nb.divideExact(g1);
  }
  const g2 = db.gcd(da);
  if (!g2.isOne() && !g2.isZero()) {
    da = da.divideExact(g2);
    db = db.divideExact(g2);
  }

  let numerator = na.multiply(db);
  let denominator = nb.multiply(da);
  if (denominator.isZero()) {
    throw withFrames(
      new PyZeroDivisionError(`Fraction(${numerator.toString()}, 0)`),
      [FRAME_DIV],
    );
  }
  if (denominator.isNegative()) {
    numerator = numerator.negate();
    denominator = denominator.negate();
  }
  return Fraction.fromCoprime(numerator, denominator);
}

/** `fraction / other` -- the `forward` half of the operator pair. */
export function trueDivideForward(a, b) {
  try {
    return divide(a, b);
  } catch (err) {
    throw prependFrame(err, FRAME_FORWARD);
  }
}

/** `value / fraction` where the left operand is an int -- the `reverse` half. */
export function trueDivideReverse(a, b) {
  try {
    return divide(a, b);
  } catch (err) {
    throw prependFrame(err, FRAME_REVERSE);
  }
}

function prependFrame(err, frame) {
  if (Array.isArray(err.pyFrames)) err.pyFrames = [frame, ...err.pyFrames];
  return err;
}

/**
 * Traceback rendering for exceptions that reach the top level.
 *
 * Two details matter for fidelity:
 *
 *  - The source line is looked up through the equivalent of `linecache`, i.e.
 *    the recorded file name resolved against the working directory.  The
 *    reference build ships no sources, so the line appears only when a
 *    `test20.py` happens to sit next to the caller -- and then it is that
 *    file's text that gets echoed.
 *  - When the line is available it is followed by the fine-grained anchors
 *    added in 3.11: `^` under the failing operator, `~` under the rest of the
 *    expression, with columns taken relative to the stripped line.
 */

import { readFileSync } from 'node:fs';

import { writeStderr } from './stdio.mjs';

const SOURCE_INDENT = '    ';

/** @type {Map<string, string[]|null>} */
const lineCache = new Map();

/** The requested source line, or null when the file cannot be consulted. */
function lookupSourceLine(file, lineNumber) {
  if (!lineCache.has(file)) {
    try {
      lineCache.set(file, readFileSync(file, 'utf8').split(/\r\n|\r|\n/));
    } catch {
      lineCache.set(file, null);
    }
  }
  const lines = lineCache.get(file);
  if (lines === null) return null;
  const line = lines[lineNumber - 1];
  return line === undefined || line === '' ? null : line;
}

/**
 * Build the anchor line for a span, in columns relative to the stripped line.
 *
 * @param {[number, number]} span  Half-open column range of the expression.
 * @param {[number, number]|null} operator  Column range of the operator token
 *   for a binary operation; `null` marks the whole span with carets.
 */
export function anchorLine(span, operator) {
  const [start, end] = span;
  let marks;
  if (operator === null) {
    marks = '^'.repeat(end - start);
  } else {
    const [operatorStart, operatorEnd] = operator;
    marks =
      '~'.repeat(operatorStart - start) +
      '^'.repeat(operatorEnd - operatorStart) +
      '~'.repeat(end - operatorEnd);
  }
  return ' '.repeat(SOURCE_INDENT.length + start) + marks;
}

/**
 * Render and emit a traceback.
 *
 * @param {{file: string, line: number, span: [number, number],
 *          operator: [number, number]|null}} origin  The `<module>` frame.
 * @param {{file: string, line: number, name: string}[]} frames
 *   Library frames below it, outermost first.  The reference build has no
 *   source for those, so only their headers are printed.
 * @param {string} exceptionLine  The trailing `Type: message` line.
 */
export function printTraceback(origin, frames, exceptionLine) {
  let out = 'Traceback (most recent call last):\n';
  out += `  File "${origin.file}", line ${origin.line}, in <module>\n`;

  const rawLine = lookupSourceLine(origin.file, origin.line);
  if (rawLine !== null) {
    const stripped = rawLine.trim();
    const indentWidth = rawLine.length - rawLine.trimStart().length;
    out += `${SOURCE_INDENT}${stripped}\n`;

    const span = [origin.span[0] - indentWidth, origin.span[1] - indentWidth];
    const operator =
      origin.operator === null
        ? null
        : [origin.operator[0] - indentWidth, origin.operator[1] - indentWidth];
    // Anchors are suppressed only when they would cover the whole line and
    // carry no operator detail.
    if (span[1] - span[0] < stripped.length || operator !== null) {
      out += `${anchorLine(span, operator)}\n`;
    }
  }

  for (const frame of frames) {
    out += `  File "${frame.file}", line ${frame.line}, in ${frame.name}\n`;
  }
  out += `${exceptionLine}\n`;
  writeStderr(out);
}
